import{_ as e,o as a,c as s,a2 as r}from"./chunks/framework.Bg-Zxr5O.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-en/Expressions.md","filePath":"manual-en/Expressions.md","lastUpdated":1785684581000}'),o={name:"manual-en/Expressions.md"};function d(n,t,i,p,l,c){return a(),s("div",null,[...t[0]||(t[0]=[r('<h2 id="_7-mathematical-expressions" tabindex="-1">7 Mathematical Expressions <a class="header-anchor" href="#_7-mathematical-expressions" aria-label="Permalink to &quot;7 Mathematical Expressions&quot;">​</a></h2><p>Expressions share a common syntax each place they appear in PSPP commands. Expressions are made up of <em>operands</em> , which can be numbers, strings, or variable names, separated by <em>operators</em>. There are five types of operators: grouping, arithmetic, logical, relational, and functions.</p><p>Every operator takes one or more operands as input and yields exactly one result as output. Depending on the operator, operands accept strings or numbers as operands. With few exceptions, operands may be full-fledged expressions in themselves.</p><table tabindex="0"><thead><tr><th>• Boolean Values</th><th></th><th>Boolean values</th></tr></thead><tbody><tr><td>• Missing Values in Expressions</td><td></td><td>Using missing values in expressions</td></tr><tr><td>• Grouping Operators</td><td></td><td>parentheses</td></tr><tr><td>• Arithmetic Operators</td><td></td><td>add sub mul div pow</td></tr><tr><td>• Logical Operators</td><td></td><td>AND NOT OR</td></tr><tr><td>• Relational Operators</td><td></td><td>EQ GE GT LE LT NE</td></tr><tr><td>• Functions</td><td></td><td>More-sophisticated operators</td></tr><tr><td>• Order of Operations</td><td></td><td>Operator precedence</td></tr></tbody></table>',4)])])}const u=e(o,[["render",d]]);export{h as __pageData,u as default};
